#!/usr/bin/env python3
"""Well-file demo pipeline: classify → extract → split → schema (W-1, plat) on RRC permit packets.

Two modes, one code path for everything after the API call:
  --mode live     calls the parser API at PULSE_BASE_URL with PULSE_API_KEY, both from the environment. No key in code.
                  PULSE_BASE_URL overrides the host (the documented VPC / self-hosted pattern).
  --mode fixture  replays fixtures/responses/<permit>.json. Fixtures are SYNTHETIC: generated by
                  make_fixtures.py from the truth files with labeled perturbations. Every output written in
                  fixture mode carries "synthetic": true. Never quote a fixture number as a Pulse result.

Endpoint shapes follow the parser's API reference (fetched 2026-09-04): /classify (multipart file + classify_config
JSON string), /extract (multipart file, detect_selections), /split (extraction_id + split_config),
/schema split mode (split_id + split_schema_config{topic: {schema, schema_prompt}} → results{topic: {values,
citations}}; fetched 2026-09-04), /schema single mode (extraction_id + schema_config{input_schema, schema_prompt}),
GET /job/{id} for async.

Schema mode (--schema-mode, default split): live-clean-02 ran /schema in single mode over the WHOLE packet, so the
W-1 schema saw the plat and the horizontal supplement pages too, and the perpendiculars came back from the wrong
place on all four horizontal packets (README failure mode 2). Split mode hands each topic only its own /split pages.
The surface-vs-terminus confusion inside the W-1 itself is handled by the schema descriptions + prompt, not by pages.

Sets: --set clean|scan runs the RRC well-file corpus (corpus/manifest.json). --set synth runs the SYNTHETIC
joint-interest month (synth/manifest.json): three packets, seven documents, classify per document then
extract -> split -> schema per packet, writing runs/<id>/<packet>.json plus runs/<id>/month.json. No real
company, person, or operator appears in the synth corpus. --variant clean|scan picks the rendering.
--corpus <dir> (implies --set synth) runs a second synth-shaped corpus: <dir>/manifest.json, <dir>/truth/, fixtures
from <dir>/fixtures/responses/; the classify/split configs stay the frozen schemas/synth_*_config.json.

Usage:
  python3 pipeline.py --mode fixture --set clean
  PULSE_API_KEY=... python3 pipeline.py --mode live --set scan --permits 918133 918289
  PULSE_API_KEY=... python3 pipeline.py --mode live --set clean --schema-mode single   # reproduce live-clean-02
  python3 make_fixtures.py --set synth && python3 pipeline.py --mode fixture --set synth --run-id fixture-synth-01
  python3 make_fixtures.py --corpus synth-pilot && python3 pipeline.py --mode fixture --corpus synth-pilot --run-id fixture-pilot-01
  PULSE_API_KEY=... python3 pipeline.py --mode live --set synth --variant clean --run-id live-synth-01
Outputs: runs/<run_id>/<permit>.json plus runs/<run_id>/raw/*.json and runs/<run_id>/run.json
"""
import argparse, json, os, pathlib, sys, time, uuid, urllib.request, urllib.error, mimetypes
from datetime import datetime, timezone

HERE = pathlib.Path(__file__).resolve().parent
CREDIT_USD = 0.015  # self-serve overage, the parser's public pricing page (2026-09-01); Enterprise is custom

# split topic → (record key, cfg key). Topic names must match schemas/split_config.json.
SCHEMA_TOPICS = {'w1_permit': ('schema_w1', 'w1'), 'plat': ('schema_plat', 'plat')}
SCHEMA_PROMPTS = {
    'w1_permit': ('Extract from the Form W-1 pages only. Copy values exactly as printed. Return null for any field not present. '
                  'Items 21 and 22 (lease line and survey line perpendiculars) are the SURFACE location on the W-1 header page. '
                  'Never take penetration point or terminus perpendiculars from the Directional/Horizontal supplement, and never '
                  'take values from a plat.'),
    'plat': 'Extract from the surveyor plat pages only. Copy values exactly as printed. Return null for any field not present.',
}


def parse_split_schema(resp: dict, topics) -> dict:
    """Split-mode /schema response → {topic: {values, citations, confidence} | None}.

    Documented shape (the parser's API reference, /schema endpoint, 2026-09-04): top-level `results` keyed by
    topic, each {values, citations}. Also accepts the same block under `schema_output` in case the live API wraps
    it like single mode does. A topic missing from the response maps to None so the caller can say so.
    """
    results = resp.get('results')
    if not isinstance(results, dict):
        results = (resp.get('schema_output') or {}).get('results') if isinstance(resp.get('schema_output'), dict) else None
    results = results if isinstance(results, dict) else {}
    out = {}
    for t in topics:
        r = results.get(t)
        out[t] = None if not isinstance(r, dict) else {'values': r.get('values') or {}, 'citations': r.get('citations') or {}, 'confidence': r.get('confidence')}
    return out


def attach_citations(rec, name, citations, extract_path: pathlib.Path):
    """Resolve element-id citations (observed live shape) to page/box/text via the saved /extract. Never fatal."""
    try:
        from resolve_live import index_extract, resolve, flatten_resolved
        idx = index_extract(json.loads(extract_path.read_text()))
        resolved = flatten_resolved(resolve(citations or {}, idx))
        rec[name]['citations'] = {k: {'page': v.get('page'), 'bbox': v.get('bbox'), 'text': v.get('text'), 'ref': v.get('ref'), 'kind': v.get('kind')} for k, v in resolved.items()}
        rec[name]['citation_note'] = f"{len(resolved)} citations resolved from element ids; {sum(1 for v in resolved.values() if v.get('unresolved'))} unresolved"
    except Exception as e:  # never lose a run over a resolver bug; the raw response is on disk
        rec[name]['citation_note'] = f'resolver failed: {e}'


# ---------------------------------------------------------------------------
# Joint-interest month (--set synth). SYNTHETIC corpus under synth/; no real
# company, person, or operator appears in it.
# ---------------------------------------------------------------------------
# TWO TICKETS IN ONE PACKET — the chosen handling, and why:
# day12 carries two field tickets of the same class. /split returns pages per
# TOPIC, and split-mode /schema is addressed by topic, not by page range, so a
# single field_ticket topic could not be schema'd twice. The split config
# therefore declares two ordered topics, field_ticket_1 and field_ticket_2, and
# the field_ticket schema runs once per topic. Topics are mapped to doc ids by
# page order: the topic with the lower first page becomes the earlier ticket in
# the manifest. FALLBACK (explicit): if only one ticket topic comes back with
# pages, its values are assigned to the manifest ticket whose pages it overlaps
# (else the first), and the other ticket's values are {} with a note saying the
# split returned no pages for it. Nothing is inferred from the other ticket.
SYNTH_TOPIC_SCHEMA = {
    'afe_cover': 'afe_cover', 'afe': 'afe', 'field_ticket_1': 'field_ticket',
    'field_ticket_2': 'field_ticket', 'hauling_log': 'hauling_log',
    'invoice': 'invoice', 'jib_statement': 'jib_statement',
}
SYNTH_PROMPT_BASE = ('Extract from these pages only. Copy values exactly as printed; never recompute a total, an '
                     'extension, or a net amount. Return null when a field is absent. One quantity in this month is '
                     'a handwritten pen entry — read it as written and do not round it.')
SYNTH_PROMPTS = {
    'afe_cover': SYNTH_PROMPT_BASE + ' The interest decimal and net share are the figures this letter states, not figures you derive.',
    'afe': SYNTH_PROMPT_BASE + ' Return one cost_lines item per printed row of the estimate table, in printed order.',
    'field_ticket_1': SYNTH_PROMPT_BASE + ' These pages are ONE field ticket. Return one line_items item per printed charge row.',
    'field_ticket_2': SYNTH_PROMPT_BASE + ' These pages are ONE field ticket, a different ticket from field_ticket_1. Return one line_items item per printed charge row.',
    'hauling_log': SYNTH_PROMPT_BASE + ' Return one loads item per printed load row, in printed order.',
    'invoice': SYNTH_PROMPT_BASE + ' Return one line_items item per printed invoice row, in printed order.',
    'jib_statement': (SYNTH_PROMPT_BASE + ' wi_decimal is the HEADER decimal. Each line\'s owner_decimal is the decimal printed '
                      'on that line: copy it exactly even when it differs from the header or from other lines.'),
}


def fixture_seconds(resp, dt):
    """Fixture responses carry the timing they stand for; live responses do not."""
    if isinstance(resp, dict) and isinstance(resp.get('_fixture_seconds'), (int, float)):
        return float(resp['_fixture_seconds'])
    return dt


class FixtureClient:
    """Replays fixtures/responses/synth/<packet>.json through the same run_synth code path as live.

    Same three methods the live client exposes, so nothing downstream of the call knows the difference.
    Every response it serves carries synthetic: true (make_fixtures.py --set synth writes them).
    """
    base = 'fixture://synth'

    def __init__(self, fixdir: pathlib.Path, packet_ids):
        self.fixdir = fixdir
        self.packets = {}
        self.classify_by_file = {}
        for pid in packet_ids:
            f = fixdir / f'{pid}.json'
            if not f.exists():
                raise SystemExit(f'no synth fixture for {pid}: run  python3 make_fixtures.py --set synth')
            j = json.loads(f.read_text())
            self.packets[pid] = j
            self.classify_by_file.update(j.get('classify') or {})
        self.current = None

    def resolve(self, r):
        return r

    def post_multipart(self, path, file_path: pathlib.Path, fields):
        name = pathlib.Path(file_path).name
        if path == '/classify':
            r = self.classify_by_file.get(name)
            if r is None:
                raise RuntimeError(f'no fixture classify response for {name}')
            return r
        if path == '/extract':
            return self.packets[self.current]['extract']
        raise RuntimeError(f'fixture client has no response for {path}')

    def post_json(self, path, payload):
        pk = self.packets[self.current]
        if path == '/split':
            return pk['split']
        if path == '/schema':
            return pk['schema']
        raise RuntimeError(f'fixture client has no response for {path}')


def _ticket_topic_map(packet_docs, splits):
    """{topic: doc_id} for this packet, including the two-ticket rule and its fallback.

    Returns (mapping, notes) where notes is {doc_id: note} for documents the split did not produce.
    """
    mapping, notes = {}, {}
    by_class = {}
    for d in packet_docs:
        by_class.setdefault(d['class'], []).append(d)
    for topic in SYNTH_TOPIC_SCHEMA:
        if topic.startswith('field_ticket'):
            continue
        docs = by_class.get(topic if topic != 'jib_statement' else 'jib_statement', [])
        if docs:
            mapping[topic] = docs[0]['doc_id']
    tickets = sorted(by_class.get('field_ticket', []), key=lambda d: min(d['pages']))
    if tickets:
        got = [(min(splits[t]), t) for t in ('field_ticket_1', 'field_ticket_2') if splits.get(t)]
        got.sort()
        if len(got) >= len(tickets):
            for (_, topic), doc in zip(got, tickets):
                mapping[topic] = doc['doc_id']
        elif len(got) == 1:
            _, topic = got[0]
            pages = set(splits[topic])
            hit = next((d for d in tickets if pages & set(d['pages'])), tickets[0])
            mapping[topic] = hit['doc_id']
            for d in tickets:
                if d['doc_id'] != hit['doc_id']:
                    notes[d['doc_id']] = ('split returned only one field-ticket topic; this ticket has no pages and no values. '
                                          'Nothing was copied from the other ticket.')
        else:
            for d in tickets:
                notes[d['doc_id']] = 'split returned no field-ticket pages; no values for this ticket'
    return mapping, notes


def run_synth(client, manifest, cfg, variant, rawdir, mode, fixdir=None):
    """One joint-interest month: classify 7 documents, then extract -> split -> schema per packet.

    Returns (month_record, {packet_id: packet_record}). The packet records keep the existing per-packet
    file style; month.json is the contract reconcile.py, pack, and the console read.
    fixdir: where fixture perturbation labels are read (None = fixtures/responses/synth; --corpus passes its own).
    """
    fixdir = fixdir or HERE / 'fixtures' / 'responses' / 'synth'
    docs = manifest['documents']
    key_file = 'file' if variant == 'clean' else 'scan_file'
    month = {'run_id': None, 'mode': mode, 'set': 'synth', 'variant': variant, 'synthetic_documents': True,
             'synthetic_responses': mode == 'fixture', 'started': now(), 'packets': {}, 'classify': [],
             'documents': {}, 'timing': {}, 'credits': {}}
    packet_recs = {}

    # 1. classify every document on its own (the routing step; catch-all present, forced choice)
    for d in docs:
        f = HERE / d[key_file]
        resp, dt = timed(lambda: client.resolve(client.post_multipart('/classify', f, {'classify_config': json.dumps(cfg['classify'])})))
        (rawdir / f"classify__{d['doc_id']}.json").write_text(json.dumps(resp, indent=1))
        co = resp.get('classify_output', resp)
        month['classify'].append({'doc_id': d['doc_id'], 'file': d[key_file],
                                  'predicted': co.get('classification') or co.get('name') or co.get('label'),
                                  'credits_used': resp.get('credits_used'), 'seconds': fixture_seconds(resp, dt)})
        month['credits']['classify'] = (month['credits'].get('classify') or 0) + (resp.get('credits_used') or 0)

    # 2. per packet: extract -> split -> schema (split mode, one call, one schema per topic)
    for pk in manifest['packets']:
        pid = pk['packet_id']
        if isinstance(client, FixtureClient):
            client.current = pid
        pf = HERE / pk[key_file]
        rec = {'packet': pid, 'mode': mode, 'set': 'synth', 'variant': variant, 'synthetic': True,
               'file': pk[key_file], 'started': now(), 'timing': {}, 'credits': {}}
        resp, dt = timed(lambda: client.resolve(client.post_multipart('/extract', pf, {'detect_selections': 'true'})))
        (rawdir / f'{pid}__extract.json').write_text(json.dumps(resp, indent=1))
        dt = fixture_seconds(resp, dt)
        ex = {'extraction_id': resp.get('extraction_id'), 'page_count': resp.get('page_count'),
              'credits_used': resp.get('credits_used'), 'failed_pages': resp.get('failed_pages', []), 'seconds': dt}
        rec['extract'] = dict(ex, words=len((resp.get('bounding_boxes') or {}).get('Words') or []))
        rec['timing']['extract'] = dt
        rec['credits']['extract'] = resp.get('credits_used')
        xid = resp.get('extraction_id')

        resp, dt = timed(lambda: client.resolve(client.post_json('/split', {'extraction_id': xid, 'split_config': cfg['split']})))
        (rawdir / f'{pid}__split.json').write_text(json.dumps(resp, indent=1))
        dt = fixture_seconds(resp, dt)
        splits = (resp.get('split_output') or {}).get('splits', {}) or {}
        sp = {'split_id': resp.get('split_id'), 'splits': splits, 'credits_used': resp.get('credits_used'), 'seconds': dt}
        rec['split'] = sp
        rec['timing']['split'] = dt
        rec['credits']['split'] = resp.get('credits_used')

        packet_docs = [d for d in docs if d['packet'] == pid]
        topics = [t for t in SYNTH_TOPIC_SCHEMA if splits.get(t)]
        mapping, notes = _ticket_topic_map(packet_docs, splits)
        sch = {'credits_used': None, 'seconds': 0.0}
        parsed = {}
        if sp['split_id'] and topics:
            payload = {'split_id': sp['split_id'],
                       'split_schema_config': {t: {'schema': cfg[SYNTH_TOPIC_SCHEMA[t]], 'schema_prompt': SYNTH_PROMPTS[t]} for t in topics}}
            resp, dt = timed(lambda: client.resolve(client.post_json('/schema', payload)))
            (rawdir / f'{pid}__schema_split.json').write_text(json.dumps(resp, indent=1))
            dt = fixture_seconds(resp, dt)
            parsed = parse_split_schema(resp, topics)
            sch = {'schema_id': resp.get('schema_id'), 'credits_used': resp.get('credits_used'), 'seconds': dt,
                   'topics': topics, 'credits_note': 'one split-mode /schema call for every topic in this packet'}
        else:
            sch['note'] = 'no split_id or no topics with pages; schema not run for this packet'
        rec['schema'] = sch
        rec['timing']['schema'] = sch['seconds']
        rec['credits']['schema'] = sch.get('credits_used')

        # 3. resolve citations through the saved /extract and write one month document per doc_id
        extract_path = rawdir / f'{pid}__extract.json'
        idx = {}
        try:
            from resolve_live import index_extract
            idx = index_extract(json.loads(extract_path.read_text()))
        except Exception as e:
            rec['citation_note'] = f'extract index failed: {e}'
        rec['documents'] = {}
        for d in packet_docs:
            topic = next((t for t, did in mapping.items() if did == d['doc_id']), None)
            r = parsed.get(topic) if topic else None
            cites = {}
            note = notes.get(d['doc_id'])
            if r is None and topic:
                note = note or 'topic sent to /schema but absent from the response; see raw/*__schema_split.json'
            if r:
                try:
                    from resolve_live import resolve, flatten_resolved
                    res = flatten_resolved(resolve(r['citations'] or {}, idx))
                    cites = {k: {'page': v.get('page'), 'bbox': v.get('bbox'), 'text': v.get('text'), 'ref': v.get('ref')} for k, v in res.items()}
                except Exception as e:
                    note = f'resolver failed: {e}'
            doc = {'class': d['class'], 'packet': pid, 'topic': topic, 'pages': (splits.get(topic) or []) if topic else [],
                   'values': (r or {}).get('values', {}) or {}, 'citations': cites,
                   'credits_used': None, 'seconds': sch['seconds'], 'note': note,
                   'credits_note': 'schema credits are per packet, not per document; see packets.<id>.schema.credits_used'}
            rec['documents'][d['doc_id']] = doc
            month['documents'][d['doc_id']] = doc
        rec['finished'] = now()
        rec['cycle_seconds'] = round(sum(v for v in rec['timing'].values() if v), 3)
        month['packets'][pid] = {'file': pk[key_file], 'pages': pk['pages'], 'extract': ex, 'split': sp, 'schema': sch,
                                 'cycle_seconds': rec['cycle_seconds']}
        if mode == 'fixture':  # carry the labelled perturbations once so reconcile, the scorer, the pack, and the console can name them
            fxp = fixdir / f'{pid}.json'
            if fxp.exists():
                for x in json.loads(fxp.read_text()).get('perturbations', []):
                    if x not in month.setdefault('fixture_perturbations', []):
                        month['fixture_perturbations'].append(x)
        packet_recs[pid] = rec

    month['finished'] = now()
    month['timing'] = {'classify': round(sum(c['seconds'] for c in month['classify']), 3),
                       'extract': round(sum(p['extract']['seconds'] or 0 for p in month['packets'].values()), 3),
                       'split': round(sum(p['split']['seconds'] or 0 for p in month['packets'].values()), 3),
                       'schema': round(sum(p['schema']['seconds'] or 0 for p in month['packets'].values()), 3)}
    for step in ('extract', 'split', 'schema'):
        month['credits'][step] = sum((p[step].get('credits_used') or 0) for p in month['packets'].values())
    total = sum(v for v in month['credits'].values() if isinstance(v, (int, float)))
    month['credits']['total'] = total
    month['cycle_seconds'] = round(sum(month['timing'].values()), 3)
    month['pages'] = sum(p['pages'] for p in month['packets'].values())
    month['cost_usd_at_list'] = round(total * CREDIT_USD, 4)
    month['cost_note'] = (f'credits_used as returned by each API call at ${CREDIT_USD} per credit self-serve list' if mode == 'live'
                          else 'SYNTHETIC fixture credits and seconds from make_fixtures.py; no API call was made; not a timing, not a cost')
    return month, packet_recs


def main_synth(a):
    """--set synth: one joint-interest month, three packets, seven documents.

    --corpus <dir> runs the same path on another synth-shaped corpus: <dir>/manifest.json, fixtures from
    <dir>/fixtures/responses/ (make_fixtures.py --corpus <dir>), frozen synth classify/split configs. The run
    record keeps set=synth and gains corpus=<dir>. Without --corpus nothing changes.
    """
    from score_synth import corpus_paths
    corpus = getattr(a, 'corpus', None)
    paths = corpus_paths(corpus)
    manifest = json.loads(paths['manifest'].read_text())
    run_id = a.run_id or f"{datetime.now().strftime('%Y%m%d-%H%M%S')}-{a.mode}-synth"
    outdir = HERE / 'runs' / run_id
    rawdir = outdir / 'raw'
    rawdir.mkdir(parents=True, exist_ok=True)
    cfg = {'classify': load('schemas/synth_classify_config.json'), 'split': load('schemas/synth_split_config.json')}
    for name in set(SYNTH_TOPIC_SCHEMA.values()):
        cfg[name] = load(f'schemas/{name}.json')
    if a.mode == 'live':
        key = os.environ.get('PULSE_API_KEY')
        if not key:
            sys.exit('DEMO HALT — PULSE_API_KEY is not set. Fixture mode needs no key: python3 pipeline.py --mode fixture --set synth')
        base = os.environ.get('PULSE_BASE_URL')
        if not base:
            sys.exit('DEMO HALT — PULSE_BASE_URL is not set (see .env.example).')
        client = PulseClient(key, base)
    else:
        if paths['label'] is not None and not paths['default']:
            ids = [p['packet_id'] for p in manifest['packets']]
            if not all((paths['fixtures'] / f'{pid}.json').exists() for pid in ids):
                raise SystemExit(f"no synth fixtures under {paths['fixtures']}: run  python3 make_fixtures.py --corpus {paths['label']}")
        client = FixtureClient(paths['fixtures'], [p['packet_id'] for p in manifest['packets']])
    print(f"[{a.mode}] synth month, variant={a.variant}, {len(manifest['packets'])} packets / {len(manifest['documents'])} documents"
          + (f", corpus={paths['label']}" if corpus is not None else '') + ' ...', flush=True)
    month, packet_recs = run_synth(client, manifest, cfg, a.variant, rawdir, a.mode, paths['fixtures'])
    month['run_id'] = run_id
    if corpus is not None:
        month['corpus'] = paths['label']
    for pid, rec in packet_recs.items():
        rec['run_id'] = run_id
        (outdir / f'{pid}.json').write_text(json.dumps(rec, indent=1))
    (outdir / 'month.json').write_text(json.dumps(month, indent=1))
    run_rec = {'run_id': run_id, 'mode': a.mode, 'set': 'synth', 'variant': a.variant,
               'synthetic': True, 'synthetic_documents': True,
               'synthetic_responses': a.mode == 'fixture',
               'packets': [p['packet_id'] for p in manifest['packets']],
               'documents': [d['doc_id'] for d in manifest['documents']],
               'base_url': getattr(client, 'base', None), 'created': now()}
    if corpus is not None:
        run_rec['corpus'] = paths['label']
    (outdir / 'run.json').write_text(json.dumps(run_rec, indent=1))
    print(f"run written: runs/{run_id}  month.json + {len(packet_recs)} packet records "
          f"(synthetic_documents=True, synthetic_responses={a.mode == 'fixture'})")



def now():
    return datetime.now(timezone.utc).isoformat(timespec='seconds')


def load(p):
    return json.loads((HERE / p).read_text())


class PulseClient:
    """Minimal stdlib client. Multipart for file uploads, JSON for the rest, poll for async jobs."""

    def __init__(self, api_key: str, base_url: str):
        self.key = api_key
        self.base = base_url.rstrip('/')

    def _req(self, method, path, body=None, headers=None, timeout=600):
        h = {'x-api-key': self.key}
        h.update(headers or {})
        req = urllib.request.Request(self.base + path, data=body, method=method, headers=h)
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return json.loads(r.read().decode('utf-8'))
        except urllib.error.HTTPError as e:
            detail = e.read().decode('utf-8', 'replace')[:600]
            raise RuntimeError(f"HTTP {e.code} on {path}: {detail}")

    def post_json(self, path, payload):
        return self._req('POST', path, json.dumps(payload).encode(), {'Content-Type': 'application/json'})

    def post_multipart(self, path, file_path: pathlib.Path, fields: dict):
        boundary = 'pulse' + uuid.uuid4().hex
        parts = []
        for k, v in fields.items():
            parts.append(f'--{boundary}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'.encode())
        ctype = mimetypes.guess_type(str(file_path))[0] or 'application/octet-stream'
        parts.append(f'--{boundary}\r\nContent-Disposition: form-data; name="file"; filename="{file_path.name}"\r\nContent-Type: {ctype}\r\n\r\n'.encode())
        parts.append(file_path.read_bytes())
        parts.append(f'\r\n--{boundary}--\r\n'.encode())
        return self._req('POST', path, b''.join(parts), {'Content-Type': f'multipart/form-data; boundary={boundary}'})

    def resolve(self, resp):
        """Follow async job ids and offloaded result URLs until a final payload is in hand."""
        for _ in range(240):
            if isinstance(resp, dict) and resp.get('job_id') and resp.get('status') in ('pending', 'processing'):
                time.sleep(5)
                resp = self._req('GET', f"/job/{resp['job_id']}")
                if resp.get('status') == 'completed' and 'result' in resp:
                    resp = resp['result']
                elif resp.get('status') in ('failed', 'canceled', 'expired'):
                    raise RuntimeError(f"job {resp.get('job_id')} {resp.get('status')}: {resp.get('error')}")
                continue
            if isinstance(resp, dict) and resp.get('is_url') and resp.get('url'):
                with urllib.request.urlopen(urllib.request.Request(resp['url'], headers={'x-api-key': self.key}), timeout=600) as r:
                    resp = json.loads(r.read().decode('utf-8'))
                continue
            return resp
        raise RuntimeError('job did not complete within the polling budget')


def timed(fn):
    t0 = time.perf_counter()
    out = fn()
    return out, round(time.perf_counter() - t0, 3)


def run_live(client, permit, packet: pathlib.Path, raw_docs, cfg, rawdir, schema_mode='split'):
    rec = {'permit': permit, 'mode': 'live', 'synthetic': False, 'started': now(), 'classify': [], 'timing': {}, 'credits': {}}
    # 1. classify each published document (the routing step; forced choice, catch-all present)
    for d in raw_docs:
        resp, dt = timed(lambda: client.resolve(client.post_multipart('/classify', HERE / d['file'], {'classify_config': json.dumps(cfg['classify'])})))
        (rawdir / f"{permit}__classify__{pathlib.Path(d['file']).stem}.json").write_text(json.dumps(resp, indent=1))
        co = resp.get('classify_output', resp)
        rec['classify'].append({'file': pathlib.Path(d['file']).name, 'predicted': co.get('classification') or co.get('name') or co.get('label'), 'credits_used': resp.get('credits_used'), 'seconds': dt, 'raw_keys': list(resp.keys())})
        rec['credits']['classify'] = (rec['credits'].get('classify') or 0) + (resp.get('credits_used') or 0)
    # 2. extract the packet
    resp, dt = timed(lambda: client.resolve(client.post_multipart('/extract', packet, {'detect_selections': 'true'})))
    (rawdir / f'{permit}__extract.json').write_text(json.dumps(resp, indent=1))
    rec['extract'] = {'extraction_id': resp.get('extraction_id'), 'page_count': resp.get('page_count'), 'credits_used': resp.get('credits_used'),
                      'failed_pages': resp.get('failed_pages', []), 'seconds': dt,
                      'words': len((resp.get('bounding_boxes') or {}).get('Words') or []),
                      'tables': len((resp.get('bounding_boxes') or {}).get('Tables') or []),
                      'selection_marks': len((resp.get('bounding_boxes') or {}).get('SelectionMarks') or [])}
    rec['timing']['extract'] = dt; rec['credits']['extract'] = resp.get('credits_used')
    xid = resp.get('extraction_id')
    # 3. split
    resp, dt = timed(lambda: client.resolve(client.post_json('/split', {'extraction_id': xid, 'split_config': cfg['split']})))
    (rawdir / f'{permit}__split.json').write_text(json.dumps(resp, indent=1))
    rec['split'] = {'split_id': resp.get('split_id'), 'splits': (resp.get('split_output') or {}).get('splits', {}), 'credits_used': resp.get('credits_used'), 'seconds': dt}
    rec['timing']['split'] = dt; rec['credits']['split'] = resp.get('credits_used')
    # 4. schema. Split mode (default): ONE /schema call with split_id + per-topic config, so the W-1 schema sees only
    #    the W-1 pages and the plat schema only the plat pages. Single mode (the live-clean-02 path) runs each schema
    #    over the whole extraction and is kept behind --schema-mode single for reproduction and as the fallback.
    splits = rec['split']['splits'] or {}
    extract_path = rawdir / f'{permit}__extract.json'
    use_split = schema_mode == 'split' and bool(rec['split'].get('split_id')) and bool(splits.get('w1_permit'))
    rec['schema_mode'] = 'split' if use_split else 'single'
    if schema_mode == 'split' and not use_split:
        rec['schema_mode_note'] = 'split mode requested but /split returned no split_id or no w1_permit pages; fell back to single mode over the whole packet'
    if use_split:
        topics = [t for t in SCHEMA_TOPICS if splits.get(t)]
        payload = {'split_id': rec['split']['split_id'],
                   'split_schema_config': {t: {'schema': cfg[SCHEMA_TOPICS[t][1]], 'schema_prompt': SCHEMA_PROMPTS[t]} for t in topics}}
        resp, dt = timed(lambda: client.resolve(client.post_json('/schema', payload)))
        (rawdir / f'{permit}__schema_split.json').write_text(json.dumps(resp, indent=1))
        parsed = parse_split_schema(resp, topics)
        rec['timing']['schema_split'] = dt; rec['credits']['schema_split'] = resp.get('credits_used')
        for t, (name, _) in SCHEMA_TOPICS.items():
            r = parsed.get(t)
            rec[name] = {'schema_id': resp.get('schema_id'), 'schema_mode': 'split', 'pages': splits.get(t) or [],
                         'values': (r or {}).get('values', {}), 'citations': (r or {}).get('citations', {}), 'citation_refs': (r or {}).get('citations', {}),
                         'confidence': (r or {}).get('confidence'), 'credits_used': None, 'seconds': dt if t in topics else 0.0,
                         'credits_note': 'one split-mode call for every topic; credits recorded under credits.schema_split'}
            if t not in topics:
                rec[name]['note'] = 'topic has no pages in /split; schema not run'
            elif r is None:
                rec[name]['note'] = 'topic sent but absent from the split-mode response; see raw/*__schema_split.json'
            else:
                attach_citations(rec, name, r['citations'], extract_path)
    else:
        for t, (name, ck) in SCHEMA_TOPICS.items():
            resp, dt = timed(lambda: client.resolve(client.post_json('/schema', {'extraction_id': xid, 'schema_config': {'input_schema': cfg[ck], 'schema_prompt': SCHEMA_PROMPTS[t]}})))
            (rawdir / f'{permit}__{name}.json').write_text(json.dumps(resp, indent=1))
            so = resp.get('schema_output') or {}
            rec[name] = {'schema_id': resp.get('schema_id'), 'schema_mode': 'single', 'pages': None, 'values': so.get('values', {}), 'citations': so.get('citations', {}),
                         'citation_refs': so.get('citations', {}), 'confidence': so.get('confidence'), 'credits_used': resp.get('credits_used'), 'seconds': dt}
            rec['timing'][name] = dt; rec['credits'][name] = resp.get('credits_used')
            attach_citations(rec, name, so.get('citations'), extract_path)
    rec['finished'] = now()
    rec['cycle_seconds'] = round(sum(rec['timing'].values()) + sum(c['seconds'] for c in rec['classify']), 3)
    credits = sum(v for v in rec['credits'].values() if isinstance(v, (int, float)))
    rec['credits']['total'] = credits
    rec['cost_usd_at_list'] = round(credits * CREDIT_USD, 4)
    rec['cost_note'] = ('credits_used as returned by each API call (classify, extract, split, schema split-mode x1) at $0.015 per credit self-serve list'
                        if use_split else 'credits_used as returned by each API call (classify, extract, split, schema x2) at $0.015 per credit self-serve list')
    return rec


def run_fixture(permit, fixtures_dir: pathlib.Path):
    p = fixtures_dir / f'{permit}.json'
    if not p.exists():
        raise SystemExit(f"no fixture for {permit}: run make_fixtures.py first")
    rec = json.loads(p.read_text())
    rec['mode'] = 'fixture'; rec['synthetic'] = True; rec['started'] = rec['finished'] = now()
    return rec


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--mode', choices=['live', 'fixture'], required=True)
    ap.add_argument('--set', choices=['clean', 'scan', 'synth'], default=None, help='default clean; --corpus implies synth')
    ap.add_argument('--corpus', help='synth-shaped corpus dir (relative to demo/ or absolute) holding manifest.json and truth/; implies --set synth')
    ap.add_argument('--variant', choices=['clean', 'scan'], default='clean', help='--set synth only: which rendering of the synthetic corpus to run')
    ap.add_argument('--permits', nargs='*')
    ap.add_argument('--run-id')
    ap.add_argument('--schema-mode', choices=['split', 'single'], default='split', help='split = /schema per split topic (default); single = whole packet (live-clean-02 path)')
    a = ap.parse_args()
    if a.corpus is not None:
        if a.set not in (None, 'synth'):
            ap.error('--corpus runs the synth path; drop --set or use --set synth')
        a.set = 'synth'
    a.set = a.set or 'clean'
    if a.set == 'synth':
        return main_synth(a)
    manifest = load('corpus/manifest.json')
    permits = a.permits or [p['permit'] for p in manifest['packets']]
    run_id = a.run_id or f"{datetime.now().strftime('%Y%m%d-%H%M%S')}-{a.mode}-{a.set}"
    outdir = HERE / 'runs' / run_id; rawdir = outdir / 'raw'; rawdir.mkdir(parents=True, exist_ok=True)
    cfg = {'classify': load('schemas/classify_config.json'), 'split': load('schemas/split_config.json'), 'w1': load('schemas/w1_permit.json'), 'plat': load('schemas/plat.json')}
    client = None
    if a.mode == 'live':
        key = os.environ.get('PULSE_API_KEY')
        if not key:
            sys.exit('DEMO HALT — PULSE_API_KEY is not set. Create the key in the parser account console (Frank creates the account, D-104) and export it. Fixture mode needs no key.')
        base = os.environ.get('PULSE_BASE_URL')
        if not base:
            sys.exit('DEMO HALT — PULSE_BASE_URL is not set (see .env.example).')
        client = PulseClient(key, base)
    results = []
    for permit in permits:
        pk = next(p for p in manifest['packets'] if p['permit'] == permit)
        packet = HERE / (pk['clean'] if a.set == 'clean' else pk['scan'])
        raw_docs = [d for d in manifest['documents'] if d['permit'] == permit]
        print(f"[{a.mode}] {permit} ({a.set}, {pk['pages']} pp) ...", flush=True)
        try:
            rec = run_live(client, permit, packet, raw_docs, cfg, rawdir, a.schema_mode) if a.mode == 'live' else run_fixture(permit, HERE / 'fixtures' / 'responses')
        except Exception as e:
            rec = {'permit': permit, 'mode': a.mode, 'error': str(e), 'started': now()}
            print(f"   ERROR {e}", file=sys.stderr)
        rec['set'] = a.set; rec['packet'] = str(packet.relative_to(HERE))
        (outdir / f'{permit}.json').write_text(json.dumps(rec, indent=1))
        results.append(rec)
    (outdir / 'run.json').write_text(json.dumps({'run_id': run_id, 'mode': a.mode, 'set': a.set, 'synthetic': a.mode == 'fixture', 'permits': permits, 'schema_mode': a.schema_mode if a.mode == 'live' else None,
                                                 'base_url': (client.base if client else None), 'created': now(),
                                                 'errors': [r['permit'] for r in results if 'error' in r]}, indent=1))
    print(f"run written: runs/{run_id}  (synthetic={a.mode == 'fixture'})")


if __name__ == '__main__':
    main()
